const items = $input.all();
const normalizedItems = [];

for (const item of items) {
  const body = item.json.body || item.json;
  const headers = item.json.headers || {};

  // ── Détection de la source ────────────────────────────────
  let sourceType = 'unknown';
  let source = 'unknown';

  if (headers['x-github-event']) {
    sourceType = 'github';
    source = 'GitHub';
  } else if (body.sonarqube || body.project?.key) {
    sourceType = 'sonarqube';
    source = 'SonarQube';
  } else if (
    body.event === 'pipeline_failed'   ||
    body.event === 'pipeline_unstable' ||
    body.event === 'pipeline_success'  ||
    body.job !== undefined             ||
    body.jenkins === true
  ) {
    sourceType = 'jenkins';
    source = 'Jenkins';
  }

  // ── Normalisation ─────────────────────────────────────────
  const normalized = {
    incidentId: body.incidentId ||
      `incident-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,

    source,
    sourceType,

    // ── Champs dynamiques — 100% depuis le payload ──────────
    // Chaque projet Jenkins fournit ces valeurs dans son Jenkinsfile
    // n8n ne connaît aucune valeur par défaut
    projectId:  body.project_id  || null,
    backendUrl: body.backend_url || null,

    // ── Métadonnées du pipeline ──────────────────────────────
    repository: body.repository?.full_name ||
                body.repository?.name      ||
                body.project?.key          ||
                body.repo                  ||
                body.job                   || null,

    branch: body.ref?.replace('refs/heads/', '') ||
            body.branch                          ||
            body.git?.branch                     || null,

    commitSha: body.after              ||
               body.head_commit?.id    ||
               body.commit             ||
               body.revision?.sha      || null,

    pullRequestNumber: body.pull_request?.number ||
                       body.number               || null,

    title: body.title ||
           (body.job
             ? `${body.job} - Build #${body.build_number || 'N/A'}`
             : null) ||
           body.head_commit?.message?.split('\n')[0] ||
           body.message ||
           'Untitled Incident',

    description: body.description          ||
                 body.build_url            ||
                 body.head_commit?.message ||
                 body.message              || '',

    severity: body.severity                     ||
              body.rule?.severity?.toLowerCase() ||
              'medium',

    environment: body.environment                ||
                 body.deployment?.environment    ||
                 'production',

    logs: body.logs         ||
          body.console_output ||
          (body.logs_url ? [body.logs_url] : []),

    changedFiles: body.commits?.[0]?.modified ||
                  body.head_commit?.modified   || [],

    // ── Sources spécifiques ──────────────────────────────────
    github:    sourceType === 'github'    ? body : null,
    sonarqube: sourceType === 'sonarqube' ? body : null,

    // ── Jenkins — sections v3.0 ──────────────────────────────
    jenkins: sourceType === 'jenkins' ? {
      event:        body.event        || null,
      job:          body.job          || null,
      build_number: body.build_number || null,
      build_url:    body.build_url    || null,
      logs_url:     body.logs_url     || null,
      status:       body.status       || null,
      severity:     body.severity     || null,
      tests:        body.tests        || {},
      sonar:        body.sonar        || {},
      trivy:        body.trivy        || {},
      owasp:        body.owasp        || {},
      zap:          body.zap          || {},
      docker:       body.docker       || {},
      deploy:       body.deploy       || {},
      nexus:        body.nexus        || {}
    } : null,

    createdAt: new Date().toISOString()
  };

  normalizedItems.push({ json: normalized });
}

return normalizedItems;

// Récupérer l'incident original depuis le bon nœud Normalize (3 branches possibles)
const getIncident = () => {
  const sources = ['Normalize Incident Payload', 'Normalize status BLOCKED', 'Normalize status RESOLVED'];
  for (const s of sources) {
    try {
      const d = $(s).first().json;
      if (d && d.jenkins) return d;
    } catch(e) {}
  }
  return $input.first().json;
};

const incident = getIncident();
const jenkins = incident.jenkins || {};
const jobName = jenkins.job || incident.repository;

// Récupérer le projet depuis Lookup Project
const projects = $('Lookup Project').all();
let project = null;
for (const item of projects) {
  const p = item.json;
  if (Array.isArray(p)) {
    project = p.find(x => x.jenkinsJobName === jobName) || p[0];
    break;
  }
  if (p.jenkinsJobName === jobName) { project = p; break; }
}
if (!project && projects.length > 0) {
  const first = projects[0].json;
  project = Array.isArray(first) ? first[0] : first;
}

// Déduire les outils activés depuis le payload Jenkins (source de vérité)
const trivyEnabled = !!(jenkins.trivy?.report_url || jenkins.trivy?.status);
const owaspEnabled = !!(jenkins.owasp?.report_url || jenkins.owasp?.status);
const zapEnabled   = !!(jenkins.zap?.report_url   || jenkins.zap?.status);

return [{
  json: {
    ...incident,
    projectId:  project?.id         || null,
    githubRepo: project?.githubRepo || null,
    projectConfig: {
      cicdTool:       project?.cicdTool       || 'jenkins',
      githubToken:    project?.githubToken    || null,
      jenkinsUrl:     project?.jenkinsUrl     || null,
      jenkinsToken:   project?.jenkinsToken   || null,
      sonarqubeUrl:   project?.sonarqubeUrl   || null,
      sonarqubeKey:   project?.sonarqubeKey   || null,
      sonarqubeToken: project?.sonarqubeToken || null,
      trivyEnabled,
      trivyReportPath: jenkins.trivy?.report_url || null,
      dockerImage:     jenkins.docker?.image_tag || null,
      owaspEnabled,
      owaspReportPath: jenkins.owasp?.report_url || null,
      zapEnabled,
      zapTargetUrl:    jenkins.zap?.target_url   || null,
      zapReportPath:   jenkins.zap?.report_url   || null,
    }
  }
}];

const incident = $('Extract Project Config').first().json;
const config = incident.projectConfig || {};
const jenkins = incident.jenkins || {};
const buildUrl = jenkins.build_url || '';

// $input = réponse directe de "Send Raw Incident to Backend"
const incidentUUID = $input.first().json.id || null;

const resolvePath = (pattern, fallback) => {
  if (pattern) return pattern.replace('{build_url}', buildUrl);
  return fallback || null;
};

return [{
  json: {
    ...incident,
    incidentUUID,
    resolvedUrls: {
      trivy: resolvePath(config.trivyReportPath, jenkins.trivy?.report_url),
      owasp: resolvePath(config.owaspReportPath, jenkins.owasp?.report_url),
      zap:   resolvePath(config.zapReportPath,   jenkins.zap?.report_url),
    },
    fetchFlags: {
      sonarqube: !!(config.sonarqubeUrl && config.sonarqubeKey && config.sonarqubeToken),
      trivy:     !!(jenkins.trivy?.report_url || config.trivyReportPath),
      owasp:     !!(jenkins.owasp?.report_url || config.owaspReportPath),
      zap:       !!(jenkins.zap?.report_url   || config.zapReportPath),
    }
  }
}];

const incident = $('Prepare Fetch URLs').first().json;
const jenkins  = incident.jenkins || {};
const config   = incident.projectConfig || {};
const flags    = incident.fetchFlags || {};

// Helper — lit un nœud fetch en ignorant les items en erreur
const safeFetch = (nodeName) => {
  try {
    const d = $(nodeName).first().json;
    if (d && !d.error) return d;
  } catch(e) {}
  return null;
};

// ── SonarQube Issues ──────────────────────────────────────
let sonarIssues = [];
const sonarData = flags.sonarqube ? safeFetch('Fetch SonarQube Issues') : null;
if (sonarData?.issues) {
  sonarIssues = sonarData.issues.map(i => ({
    key:       i.key,
    severity:  i.severity,
    type:      i.type,
    message:   i.message,
    component: i.component?.split(':').pop() || '',
    line:      i.line || null,
    effort:    i.effort || null,
    url:       `${config.sonarqubeUrl}/project/issues?id=${config.sonarqubeKey}&open=${i.key}`
  }));
}

// ── Trivy CVEs ────────────────────────────────────────────
let trivyCVEs = [];
const trivyData = flags.trivy ? safeFetch('Fetch Trivy Report') : null;
if (trivyData?.Results) {
  trivyData.Results.forEach(r => {
    (r.Vulnerabilities || []).forEach(v => {
      if (['CRITICAL','HIGH','MEDIUM'].includes(v.Severity)) {
        trivyCVEs.push({
          id:          v.VulnerabilityID,
          severity:    v.Severity,
          package:     v.PkgName,
          version:     v.InstalledVersion,
          fixedIn:     v.FixedVersion || 'no fix available',
          description: (v.Description || '').substring(0, 200)
        });
      }
    });
  });
}

// ── ZAP Alerts ───────────────────────────────────────────
let zapAlerts = [];
const zapData = flags.zap ? safeFetch('Fetch ZAP Report') : null;
if (zapData?.site) {
  zapData.site.forEach(site => {
    (site.alerts || []).forEach(alert => {
      if (['High','Medium'].includes(alert.riskdesc?.split(' ')[0])) {
        zapAlerts.push({
          name:        alert.alert,
          risk:        alert.riskdesc,
          description: (alert.desc || '').substring(0, 200),
          solution:    (alert.solution || '').substring(0, 200),
          url:         alert.instances?.[0]?.uri || '',
          count:       alert.count || 1
        });
      }
    });
  });
}

// ── OWASP CVEs ────────────────────────────────────────────
let owaspCVEs = [];
const owaspData = flags.owasp ? safeFetch('Fetch OWASP Report') : null;
if (owaspData?.dependencies) {
  owaspData.dependencies.forEach(dep => {
    (dep.vulnerabilities || []).forEach(v => {
      if (['CRITICAL','HIGH'].includes(v.severity)) {
        owaspCVEs.push({
          id:          v.name,
          severity:    v.severity,
          package:     dep.fileName,
          description: (v.description || '').substring(0, 200),
          cvssScore:   v.cvssv3?.baseScore || v.cvssv2?.score || 0
        });
      }
    });
  });
}

// ── Données structurées du payload Jenkins ────────────────
const tests  = jenkins.tests  || {};
const sonar  = jenkins.sonar  || {};
const trivy  = jenkins.trivy  || {};
const owasp  = jenkins.owasp  || {};
const zap    = jenkins.zap    || {};
const deploy = jenkins.deploy || {};
const docker = jenkins.docker || {};

return [{
  json: {
    ...incident,
    enrichedData: {
      build: {
        job:    jenkins.job          || 'unknown',
        number: jenkins.build_number || 'N/A',
        status: jenkins.status       || 'UNKNOWN',
        url:    jenkins.build_url    || ''
      },
      tests: {
        status:   tests.status   || 'UNKNOWN',
        total:    tests.total    || 0,
        failures: tests.failures || 0,
        skipped:  tests.skipped  || 0,
        coverage: tests.coverage || '0'
      },
      sonar: {
        status:          sonar.status          || 'UNKNOWN',
        quality_gate:    sonar.quality_gate    || 'UNKNOWN',
        bugs:            sonar.bugs            || 0,
        vulnerabilities: sonar.vulnerabilities || 0,
        code_smells:     sonar.code_smells     || 0,
        coverage:        sonar.coverage        || '0',
        issues:          sonarIssues,
        issues_count:    sonarIssues.length
      },
      trivy: {
        status:     trivy.status   || 'UNKNOWN',
        critical:   trivy.critical || 0,
        high:       trivy.high     || 0,
        error:      trivy.error    || '',
        cves:       trivyCVEs,
        cves_count: trivyCVEs.length
      },
      owasp: {
        status:     owasp.status   || 'UNKNOWN',
        critical:   owasp.critical || 0,
        high:       owasp.high     || 0,
        error:      owasp.error    || '',
        cves:       owaspCVEs,
        cves_count: owaspCVEs.length
      },
      zap: {
        status:        zap.status        || 'UNKNOWN',
        alerts_high:   zap.alerts_high   || 0,
        alerts_medium: zap.alerts_medium || 0,
        alerts_low:    zap.alerts_low    || 0,
        error:         zap.error         || '',
        target_url:    zap.target_url    || '',
        alerts:        zapAlerts,
        alerts_count:  zapAlerts.length
      },
      deploy: {
        status:    deploy.status    || 'UNKNOWN',
        namespace: deploy.namespace || '',
        app_url:   deploy.app_url   || ''
      },
      docker: {
        build_status: docker.build_status || 'UNKNOWN',
        push_status:  docker.push_status  || 'UNKNOWN',
        image_tag:    docker.image_tag    || '',
        registry:     docker.registry     || ''
      }
    }
  }
}];

const input = $input.first().json;
const d = input.enrichedData || {};

const systemPrompt = `You are an elite Root Cause Analysis expert for CI/CD DevSecOps pipelines.
Analyze ALL the structured data and identify the main root cause.
Return ONLY valid JSON — no markdown, no backticks, no explanation.
Return EXACTLY:
{"incidentId":"string","errorType":"string","rootCause":"string","severityScore":0,"affectedComponent":"string","analysisSummary":"string","confidence":0.0}`;

const userContent = `Root Cause Analysis:

BUILD: ${d.build?.job} #${d.build?.number} — ${d.build?.status}

TESTS: total=${d.tests?.total}, failures=${d.tests?.failures}, status=${d.tests?.status}, coverage=${d.tests?.coverage}%

SONAR: quality_gate=${d.sonar?.quality_gate}, bugs=${d.sonar?.bugs}, vulnerabilities=${d.sonar?.vulnerabilities}, code_smells=${d.sonar?.code_smells}
SONAR ISSUES (${d.sonar?.issues_count} total):
${JSON.stringify(d.sonar?.issues?.slice(0,5) || [])}

TRIVY: status=${d.trivy?.status}, critical=${d.trivy?.critical}, high=${d.trivy?.high}, error="${d.trivy?.error}"
TRIVY CVEs (${d.trivy?.cves_count} total):
${JSON.stringify(d.trivy?.cves?.slice(0,5) || [])}

OWASP: status=${d.owasp?.status}, critical=${d.owasp?.critical}, high=${d.owasp?.high}, error="${d.owasp?.error}"

ZAP: status=${d.zap?.status}, alerts_high=${d.zap?.alerts_high}, error="${d.zap?.error}"
ZAP ALERTS (${d.zap?.alerts_count} total):
${JSON.stringify(d.zap?.alerts?.slice(0,3) || [])}

DEPLOY: status=${d.deploy?.status}, app_url=${d.deploy?.app_url}
DOCKER: build=${d.docker?.build_status}, push=${d.docker?.push_status}, image=${d.docker?.image_tag}`;

const body = { model: 'claude-haiku-4-5-20251001', max_tokens: 10000, system: systemPrompt, messages: [{ role: 'user', content: userContent }] };
return [{ json: { ollamaBodyString: JSON.stringify(body) } }];

const input = $input.first().json;
const d = input.enrichedData || {};

const systemPrompt = `You are a DevSecOps Security Risk expert.
Analyze ALL security scan results and provide a complete risk assessment.
Return ONLY valid JSON — no markdown, no backticks, no explanation.
Return EXACTLY:
{"incidentId":"string","riskLevel":"LOW","riskScore":0,"vulnerabilities":["string"],"safeToApply":true,"securitySummary":"string","confidence":0.0}`;

const userContent = `Security Risk Analysis:

BUILD: ${d.build?.job} #${d.build?.number} — ${d.build?.status}

TRIVY CONTAINER SCAN:
  status: ${d.trivy?.status}, critical: ${d.trivy?.critical}, high: ${d.trivy?.high}
  error: "${d.trivy?.error}"
  CVEs (${d.trivy?.cves_count}):
  ${JSON.stringify(d.trivy?.cves?.slice(0,10) || [])}

OWASP DEPENDENCY CHECK:
  status: ${d.owasp?.status}, critical: ${d.owasp?.critical}, high: ${d.owasp?.high}
  CVEs: ${JSON.stringify(d.owasp?.cves?.slice(0,5) || [])}

ZAP DAST SCAN:
  status: ${d.zap?.status}, alerts_high: ${d.zap?.alerts_high}, alerts_medium: ${d.zap?.alerts_medium}
  target: ${d.zap?.target_url}, error: "${d.zap?.error}"
  Alerts: ${JSON.stringify(d.zap?.alerts?.slice(0,5) || [])}

SONAR SECURITY:
  vulnerabilities: ${d.sonar?.vulnerabilities}, quality_gate: ${d.sonar?.quality_gate}
  Security Issues: ${JSON.stringify(d.sonar?.issues?.filter(i => i.type === 'VULNERABILITY')?.slice(0,5) || [])}`;

const body = { model: 'claude-haiku-4-5-20251001', max_tokens: 10000, system: systemPrompt, messages: [{ role: 'user', content: userContent }] };
return [{ json: { ollamaBodyString: JSON.stringify(body) } }];

const input = $input.first().json;
const d = input.enrichedData || {};

const systemPrompt = `You are a DevSecOps Remediation Engineer.
Analyze the pipeline data and provide ONE remediation plan covering the most critical issues.

ABSOLUTE RULES:
- Return ONLY a single raw JSON object
- NO array, NO markdown, NO backticks, NO code blocks, NO escaped JSON strings
- Start your response with { and end with }
- Each fixStep is a short actionable command (max 120 chars)
- Maximum 4 fixSteps

RETURN EXACTLY THIS STRUCTURE:
{"incidentId":"string","fixDescription":"string","fixSteps":["step1","step2","step3"],"codePatch":"","autoFixable":false,"confidence":0.9}`;

const userContent = `Remediation Plan for DevSecOps Pipeline:

BUILD: ${d.build?.job || 'unknown'} #${d.build?.number || 'N/A'} — ${d.build?.status || 'UNKNOWN'}

TESTS: total=${d.tests?.total || 0}, failures=${d.tests?.failures || 0}, status=${d.tests?.status || 'UNKNOWN'}

SONAR: quality_gate=${d.sonar?.quality_gate || 'UNKNOWN'}, bugs=${d.sonar?.bugs || 0}, vulnerabilities=${d.sonar?.vulnerabilities || 0}
Issues: ${JSON.stringify(d.sonar?.issues?.slice(0,3) || [])}

TRIVY: status=${d.trivy?.status || 'UNKNOWN'}, critical=${d.trivy?.critical || 0}, high=${d.trivy?.high || 0}, error="${d.trivy?.error || ''}"
CVEs: ${JSON.stringify(d.trivy?.cves?.slice(0,3) || [])}

OWASP: status=${d.owasp?.status || 'UNKNOWN'}, error="${d.owasp?.error || ''}"

ZAP: status=${d.zap?.status || 'UNKNOWN'}, alerts_high=${d.zap?.alerts_high || 0}, error="${d.zap?.error || ''}"
Alerts: ${JSON.stringify(d.zap?.alerts?.slice(0,3) || [])}

DEPLOY: status=${d.deploy?.status || 'UNKNOWN'}, app_url=${d.deploy?.app_url || ''}

Identify the most critical issues and provide exact fix steps with commands.`;

const body = {
  model: 'claude-haiku-4-5-20251001',
  max_tokens: 500,
  system: systemPrompt,
  messages: [{ role: 'user', content: userContent }]
};

return [{ json: { ollamaBodyString: JSON.stringify(body) } }];

const response = $input.first().json;
const content = response.content?.[0]?.text || '';
if (!content) return [{ json: { incidentId:'empty', errorType:'NO_RESPONSE', rootCause:'Agent returned empty response', severityScore:0, affectedComponent:'AI Agent', analysisSummary:'No analysis available', confidence:0.0 } }];
let clean = content.replace(/```json\s*/gi,'').replace(/```\s*/gi,'').trim();
const start = clean.indexOf('{'); const end = clean.lastIndexOf('}');
if (start===-1||end===-1) return [{ json: { incidentId:'no-json', errorType:'PARSE_ERROR', rootCause:clean.substring(0,300), severityScore:3, affectedComponent:'Unknown', analysisSummary:clean.substring(0,500), confidence:0.3 } }];
try { return [{ json: JSON.parse(clean.substring(start,end+1)) }]; }
catch(e) { return [{ json: { incidentId:'parse-failed', errorType:'JSON_ERROR', rootCause:clean.substring(0,300), severityScore:3, affectedComponent:'Unknown', analysisSummary:clean.substring(0,500), confidence:0.3 } }]; }

const response = $input.first().json;
const content = response.content?.[0]?.text || '';
if (!content) return [{ json: { incidentId:'empty', riskLevel:'UNKNOWN', riskScore:0, vulnerabilities:[], safeToApply:false, securitySummary:'No security analysis', confidence:0.0 } }];
let clean = content.replace(/```json\s*/gi,'').replace(/```\s*/gi,'').trim();
const start = clean.indexOf('{'); const end = clean.lastIndexOf('}');
if (start===-1||end===-1) return [{ json: { incidentId:'no-json', riskLevel:'UNKNOWN', riskScore:0, vulnerabilities:[], safeToApply:false, securitySummary:clean.substring(0,500), confidence:0.3 } }];
try { return [{ json: JSON.parse(clean.substring(start,end+1)) }]; }
catch(e) { return [{ json: { incidentId:'parse-failed', riskLevel:'UNKNOWN', riskScore:0, vulnerabilities:[], safeToApply:false, securitySummary:clean.substring(0,500), confidence:0.3 } }]; }

const response = $input.first().json;
const content = response.content?.[0]?.text || '';

const fallback = (msg) => [{ json: {
  incidentId: 'parse-issue',
  fixDescription: msg.substring(0, 300),
  fixSteps: [msg.substring(0, 150)],
  codePatch: '',
  autoFixable: false,
  confidence: 0.3
}}];

if (!content) return [{ json: { incidentId:'empty', fixDescription:'No remediation available', fixSteps:[], codePatch:'', autoFixable:false, confidence:0.0 } }];

let clean = content.replace(/```json\s*/gi,'').replace(/```\s*/gi,'').trim();

// Cas 1 — Claude retourne un array → prendre le 1er élément
const arrStart = clean.indexOf('[');
const objStart = clean.indexOf('{');

if (arrStart !== -1 && (objStart === -1 || arrStart < objStart)) {
  const arrEnd = clean.lastIndexOf(']');
  try {
    const arr = JSON.parse(clean.substring(arrStart, arrEnd + 1));
    const first = Array.isArray(arr) && arr.length ? arr[0] : null;
    if (first && first.fixDescription) return [{ json: first }];
  } catch(e) {}
}

// Cas 2 — objet JSON standard
const objEnd = clean.lastIndexOf('}');
if (objStart === -1 || objEnd === -1) return fallback(clean);

try {
  const parsed = JSON.parse(clean.substring(objStart, objEnd + 1));
  // Cas 3 — JSON escapé dans fixDescription (double encodage)
  if (typeof parsed.fixDescription === 'string' && parsed.fixDescription.trim().startsWith('{')) {
    try {
      const inner = JSON.parse(parsed.fixDescription);
      if (inner.fixDescription) return [{ json: inner }];
    } catch(e) {}
  }
  return [{ json: parsed }];
} catch(e) {
  return fallback(clean);
}

const items = $input.all();
const rootCause   = items[0]?.json || {};
const security    = items[1]?.json || {};
const remediation = items[2]?.json || {};
const incident    = $('Extract Project Config').first().json;
const body = {
  type: 'combined',
  projectId: incident.projectId,
  rawData: { rootCause, security, remediation },
  securityScore: security.riskScore || 0,
  riskLevel: security.riskLevel || 'LOW'
};
return [{ json: { ...body, bodyString: JSON.stringify(body) } }];

const items = $input.all();
if (items.length < 3) {
  throw new Error(`Le Judge Agent attend 3 résultats, mais il a reçu ${items.length} élément(s).`);
}

const rootCause   = items[0]?.json ?? {};
const security    = items[1]?.json ?? {};
const remediation = items[2]?.json ?? {};

const incidentNode    = $('Extract Project Config');
const fetchedDataNode = $('Merge All Fetched Data');

if (!incidentNode.isExecuted) throw new Error('Le nœud "Extract Project Config" n\'a pas été exécuté.');
if (!fetchedDataNode.isExecuted) throw new Error('Le nœud "Merge All Fetched Data" n\'a pas été exécuté.');

const incident    = incidentNode.first().json ?? {};
const fetchedData = fetchedDataNode.first().json ?? {};
const enriched    = fetchedData.enrichedData ?? {};

// ── CVEs Trivy ────────────────────────────────────────────────
const cves         = enriched.trivy?.cves ?? [];
const criticalCves = cves.filter(c => c.severity === 'CRITICAL').length;
const highCves     = cves.filter(c => c.severity === 'HIGH').length;

// ── SonarQube issues ──────────────────────────────────────────
const sonarIssues   = enriched.sonar?.issues ?? [];
const blockers      = sonarIssues.filter(i => i.severity === 'BLOCKER').length;
const bugs          = sonarIssues.filter(i => i.type === 'BUG').length;
const criticalVulns = sonarIssues.filter(i => i.severity === 'CRITICAL' && i.type === 'VULNERABILITY').length;
const codeBugs      = sonarIssues.filter(i => ['BUG', 'VULNERABILITY'].includes(i.type)).length;

// ── RemediationAgent ──────────────────────────────────────────
const autoFixable     = remediation.autoFixable === true;
const remediationPlan = remediation.fixSteps ?? remediation.steps ?? null;

// ── PRE-PROCESSOR : décision déterministe ─────────────────────
const preDecision =
  (blockers > 0 || bugs > 0 || criticalVulns > 0)
    ? 'AUTO_FIX'
    : criticalCves > 0
    ? 'BLOCK'
    : 'NOTIFY_ONLY';

const preDecisionReason =
  `blockers=${blockers}, bugs=${bugs}, criticalVulns=${criticalVulns}, criticalCves=${criticalCves}, highCves=${highCves}`;

// ── Payload final ─────────────────────────────────────────────
const judgePayload = {
  incidentId:   incident.incidentId ?? null,
  job:          incident.jenkins?.job          ?? incident.job          ?? null,
  build_number: incident.jenkins?.build_number ?? incident.build_number ?? null,
  status:       incident.jenkins?.status       ?? incident.status       ?? 'UNKNOWN',
  enrichedData:         enriched,
  rootCauseAnalysis:    rootCause,
  securityRiskAnalysis: security,
  remediationAnalysis:  remediation,
  preCalculatedDecision: preDecision,
  preCalculatedReason:   preDecisionReason,
  decisionContext: {
    deploymentSafe:  criticalCves === 0,
    blockDeployment: criticalCves > 0,
    codeFixPossible: blockers > 0 || bugs > 0 || criticalVulns > 0,
    autoFixable,
    vulnerabilitySummary: {
      criticalCves,
      highCves,
      sonarBlockers:      blockers,
      sonarBugs:          bugs,
      sonarCriticalVulns: criticalVulns,
      totalCodeIssues:    codeBugs,
    },
    mandate: `MANDATORY: Use preCalculatedDecision="${preDecision}" as your decision. Reason: ${preDecisionReason}. Only override if you detect critical security risk not captured in the data.`,
  },
};

return [{ json: { judgeInput: JSON.stringify(judgePayload) } }];

const response = $input.first().json;
const content = response.content?.[0]?.text || '';
let parsed;
try {
  let cleaned = content.trim();
  const firstBrace = cleaned.indexOf('{');
  const lastBrace = cleaned.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace !== -1) cleaned = cleaned.substring(firstBrace, lastBrace+1);
  cleaned = cleaned.replace(/```json\n?/g,'').replace(/```\n?/g,'');
  parsed = JSON.parse(cleaned);
} catch(e) {
  const extract = (key) => { const m = content.match(new RegExp('"'+key+'"\\s*:\\s*"([^"]*)"')); return m?m[1]:null; };
  const extractNum = (key) => { const m = content.match(new RegExp('"'+key+'"\\s*:\\s*(\\d+)')); return m?parseInt(m[1]):0; };
  parsed = { decision:extract('decision')||'NOTIFY_ONLY', confidenceScore:extractNum('confidenceScore'), securityLevel:extract('securityLevel')||'LOW', decisionReason:'Parse error: '+e.message, errorsSummary:extract('errorsSummary')||'', cicdIssues:'', securityIssues:'', agentActions:'', developerActions:'', recommendations:'' };
}
if (parsed.reasoning && !parsed.decisionReason) parsed.decisionReason = parsed.reasoning;
return [{ json: parsed }];

const judge    = $('Judge - Parse Output').first().json;
const incident = $('Extract Project Config').first().json;
const enriched = $('Merge All Fetched Data').first().json.enrichedData || {};
const agg      = $('Merge Agent Reports').first()?.json || {};

// Lire securityLevel depuis le bon champ
const securityLevel = (judge.securityLevel || judge.security_level || 'LOW').toUpperCase();
const decision      = judge.decision || 'NOTIFY_ONLY';
const projectId     = incident.projectId || '54192eca-43da-4d8f-9b49-30c143983fdd';

// Score basé sur securityLevel ET decision
const computeScore = (level, dec) => {
  if (level === 'CRITICAL' || dec === 'BLOCK')      return 10;
  if (level === 'HIGH')                              return 30;
  if (level === 'MEDIUM')                            return 60;
  if (level === 'LOW'    && dec === 'AUTO_FIX')      return 75;
  return 90;
};

const aiSummary = JSON.stringify({
  build:  enriched.build?.number,
  job:    enriched.build?.job,
  status: enriched.build?.status,
  ...judge
});

const incidentUUID = $('Prepare Fetch URLs').first().json.incidentUUID || null;
return [{
  json: {
    incidentUUID,
    type:     'combined',
    projectId,
    aiSummary,
    rawData: {
      rootCause:    agg.rootCauseAnalysis    || {},
      security:     agg.securityRiskAnalysis || {},
      remediation:  agg.remediationAnalysis  || {},
      enrichedData: enriched
    },
    securityScore: computeScore(securityLevel, decision),
    riskLevel:     securityLevel.toLowerCase()
  }
}];

const body = $input.first().json.body || $input.first().json;
return [{ json: {
  incidentId: `incident-${Date.now()}-${Math.random().toString(36).substr(2,9)}`,
  source: 'Jenkins', sourceType: 'jenkins',
  title: `${body.job||'Unknown'} - Build #${body.build_number||'N/A'} - BLOCKED`,
  description: body.build_url || '', severity: 'high', environment: 'production',
  jenkins: { event:body.event, job:body.job, build_number:body.build_number, build_url:body.build_url, logs_url:body.logs_url, status:'BLOCKED', tests:body.tests||{}, sonar:body.sonar||{}, trivy:body.trivy||{}, owasp:body.owasp||{}, zap:body.zap||{}, docker:body.docker||{}, deploy:body.deploy||{} },
  createdAt: new Date().toISOString()
}}];

const raw = $input.first().json; const body = raw.body || raw;
return [{ json: {
  incidentId: 'incident-'+Date.now()+'-success',
  source:'Jenkins', sourceType:'jenkins',
  branch: body.branch||'main', severity:'LOW',
  jenkins: { job:body.job||'unknown', build_number:body.build_number||'N/A', build_url:body.build_url||'', logs_url:body.logs_url||'', status:'SUCCESS', tests:body.tests||{}, sonar:body.sonar||{}, trivy:body.trivy||{}, owasp:body.owasp||{}, zap:body.zap||{}, docker:body.docker||{}, deploy:body.deploy||{}, nexus:body.nexus||{} },
  project_id: body.project_id||null,
  createdAt: new Date().toISOString()
}}];
